def solve(grid):
    # Determine filled cells (non‑zero)
    filled = [(r, c) for r in range(3) for c in range(3) if grid[r][c] != 0]

    # ----- count L‑shapes (unique unordered pairs of orthogonal neighbours) -----
    L_set = set()
    for pr, pc in filled:
        hor = []
        ver = []
        # left
        if pc - 1 >= 0 and grid[pr][pc - 1] != 0:
            hor.append((pr, pc - 1))
        # right
        if pc + 1 < 3 and grid[pr][pc + 1] != 0:
            hor.append((pr, pc + 1))
        # up
        if pr - 1 >= 0 and grid[pr - 1][pc] != 0:
            ver.append((pr - 1, pc))
        # down
        if pr + 1 < 3 and grid[pr + 1][pc] != 0:
            ver.append((pr + 1, pc))

        # form unordered pairs consisting of one horizontal and one vertical neighbour
        for h in hor:
            for v in ver:
                pair = (h, v) if h < v else (v, h)   # canonical ordering
                L_set.add(pair)

    # ----- count full lines (three non‑zero cells in a row, column or diagonal) -----
    line_cnt = 0
    # rows
    for r in range(3):
        if grid[r][0] != 0 and grid[r][1] != 0 and grid[r][2] != 0:
            line_cnt += 1
    # columns
    for c in range(3):
        if grid[0][c] != 0 and grid[1][c] != 0 and grid[2][c] != 0:
            line_cnt += 1
    # main diagonal
    if grid[0][0] != 0 and grid[1][1] != 0 and grid[2][2] != 0:
        line_cnt += 1
    # anti diagonal
    if grid[0][2] != 0 and grid[1][1] != 0 and grid[2][0] != 0:
        line_cnt += 1

    result = len(L_set) + line_cnt
    return [[result]]

